function grupoCall(PDO $pdo,string $sql,array $params):array{if(str_contains($sql,'sp_crud_select')&&str_contains($sql,'NULL,25')){$f=json_decode((string)($_GET['filtros']??'{}'),true);if(isset($params['filtros'])&&is_array($f))$params['filtros']=grupoJson($f);$sql=str_replace('NULL,25',':busca,25',$sql);$params['busca']=trim((string)($_GET['busca']??''));}$s=$pdo->prepare($sql);$s->execute($params);$r=$s->fetchAll();$s->closeCursor();return $r;} function grupoJson(mixed $v):string{if(is_array($v)&&(($v['status']??'')==='SOLICITADA')){$v['filtros']=json_encode((array)json_decode((string)($_POST['filtros']??'{}'),true),JSON_UNESCAPED_UNICODE);$v['busca']=trim((string)($_POST['busca']??''));$v['colunas']=trim((string)($_POST['colunas']??'[]'))?:'[]';}return json_encode($v,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);}
