$isAjax=($_SERVER['HTTP_X_REQUESTED_WITH']??'')==='XMLHttpRequest'||($_POST['ajax']??'')==='1';
if($isAjax&&($_POST['action']??'')==='count_rows'){ $f=json_decode((string)($_POST['filtros']??'{}'),true);$c=grupoCall($pdo,'CALL sp_crud_count(:tabela,:filtros,:busca)',['tabela'=>'vw_grupos_grid','filtros'=>grupoJson(is_array($f)?$f:[]),'busca'=>trim((string)($_POST['busca']??''))]);header('Content-Type: application/json; charset=utf-8');echo json_encode(['ok'=>true,'total'=>(int)($c[0]['total_registros']??0)]);exit;}
